import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); long n = Long.parseLong(st.nextToken()); long m = Long.parseLong(st.nextToken()); List<Long> res = new ArrayList<>(); res.add(n); for (int i = 0; i < 62; i++) { if (((n >> i) & 1) == 0) { long val = n | (1L << i); if (val <= m) { res.add(val); } } } if (res.size() < 2) { out.println("-1"); } else { out.println(res.size()); StringBuilder sb = new StringBuilder(); for (int i = 0; i < res.size(); i++) { sb.append(res.get(i)).append(i == res.size() - 1 ? "" : " "); } out.println(sb.toString()); } } out.flush(); out.close(); } }